#include <libtorrent/aux_/bandwidth_manager.hpp>
#include <libtorrent/aux_/biglybtc_shared_quota.hpp>
#include <atomic>
#include <array>
#include <iostream>
#include <stdexcept>
#include <thread>
namespace lt=libtorrent;namespace aux=lt::aux;
int checks=0;void require(bool x,const char* message){++checks;if(!x)throw std::runtime_error(message);}
struct Clock {std::atomic<std::int64_t> now{0};static std::int64_t get(void* p)noexcept{return static_cast<Clock*>(p)->now.load();}};
struct Scope {Clock clock;void* value=aux::make_shared_quota_scope(Clock::get,&clock);~Scope(){biglybtc_shared_quota_scope_close_v1(value);biglybtc_shared_quota_scope_release_v1(value);}};
struct Budget {biglybtc_shared_quota_v1 ops;Budget(Scope& s,std::uint64_t tag,int up,int down){require(!biglybtc_shared_quota_acquire_v1(s.value,tag,up,down,&ops),"create budget");}~Budget(){ops.release_budget(ops.budget);}};
struct Socket:aux::bandwidth_socket {int total=0;bool disconnecting=false;void assign_bandwidth(int,int n)override{total+=n;}bool is_disconnecting()const override{return disconnecting;}};
void localFraction(){for(int rate=1;rate<=10;++rate){aux::bandwidth_channel channel;channel.throttle(rate);int total=0;for(int tick=0;tick<100;++tick){channel.update_quota(100);int n=channel.quota_left();total+=n;channel.use_quota(n);channel.throttle(rate);}require(total==rate*10,"actual SDK local fraction/noop loses or inflates tiny rate");}}
void twoManagers(){
 for(int rate=1;rate<=10;++rate){Scope scope;Budget budget(scope,1,rate,0);aux::bandwidth_channel a,b;require(a.bind_shared(budget.ops,0)&&b.bind_shared(budget.ops,0),"bind shared channel");aux::bandwidth_manager first(0),second(0);require(first.bind_shared_scope(budget.ops)&&second.bind_shared_scope(budget.ops),"bind arbiter");auto x=std::make_shared<Socket>(),y=std::make_shared<Socket>();aux::bandwidth_channel* ax[]={&a};aux::bandwidth_channel* by[]={&b};
  for(int tick=0;tick<100;++tick){if(!first.queue_size())require(first.request_bandwidth(x,1,1,ax,1)==0,"queue owner one");if(!second.queue_size())require(second.request_bandwidth(y,1,1,by,1)==0,"queue owner two");scope.clock.now+=100000000;first.update_quotas(lt::milliseconds(100));second.update_quotas(lt::milliseconds(100));}
  require(x->total+y->total==rate*10,"two actual managers duplicate the clock or lose quota");require(x->total>0&&y->total>0,"one continuously pending manager starved");require(std::abs(x->total-y->total)<=rate+1,"equal manager demand unfair");first.close();second.close();
 }
}
void refundAndClosure(){Scope scope;Budget budget(scope,1,10,0);aux::bandwidth_channel a,b;a.bind_shared(budget.ops,0);b.bind_shared(budget.ops,0);aux::bandwidth_manager first(0),second(0);first.bind_shared_scope(budget.ops);second.bind_shared_scope(budget.ops);auto x=std::make_shared<Socket>(),y=std::make_shared<Socket>();aux::bandwidth_channel* ax[]={&a};aux::bandwidth_channel* by[]={&b};first.request_bandwidth(x,1000,1,ax,1);scope.clock.now=1000000000;first.update_quotas(lt::milliseconds(1000));require(!x->total,"partial quota delivered before TTL");x->disconnecting=true;first.update_quotas(lt::milliseconds(0));require(!x->total&&!first.queue_size(),"disconnect did not retire partial request");second.request_bandwidth(y,10,1,by,1);second.update_quotas(lt::milliseconds(0));require(y->total==10,"unused assigned quota was not returned to common budget");
 require(!biglybtc_shared_quota_set_v1(budget.ops.budget,0,0),"unlimit context");biglybtc_shared_quota_scope_close_v1(scope.value);auto z=std::make_shared<Socket>();second.request_bandwidth(z,10,1,by,1);scope.clock.now+=1000000000;second.update_quotas(lt::milliseconds(1000));require(!z->total,"closed zero-limit shared context escaped as unlimited");first.close();second.close();}
void intersectingBudgets(){Scope scope;Budget one(scope,1,10,0),two(scope,2,10,0);aux::bandwidth_channel a1,a2,b1,b2;a1.bind_shared(one.ops,0);a2.bind_shared(two.ops,0);b1.bind_shared(one.ops,0);b2.bind_shared(two.ops,0);scope.clock.now=1000000000;a1.use_quota(5);b2.use_quota(5);aux::bandwidth_manager first(0),second(0);first.bind_shared_scope(one.ops);second.bind_shared_scope(two.ops);auto x=std::make_shared<Socket>(),y=std::make_shared<Socket>();aux::bandwidth_channel* ac[]={&a1,&a2};aux::bandwidth_channel* bc[]={&b1,&b2};first.request_bandwidth(x,1,1,ac,2);second.request_bandwidth(y,1,1,bc,2);for(int n=0;n<100;++n){scope.clock.now+=100000000;first.update_quotas(lt::milliseconds(100));second.update_quotas(lt::milliseconds(100));}require(x->total==1&&y->total==1,"intersecting shared tags deadlocked after independent prior traffic");first.close();second.close();}
void globalComposition(){for(const auto limits:std::array<std::array<int,2>,2>{{{8,12},{20,8}}}){Scope scope;Budget global(scope,99,limits[0],0),tag(scope,1,limits[1],0);aux::bandwidth_channel a1,a2,b1,b2;a1.bind_shared(global.ops,0);b1.bind_shared(global.ops,0);a2.bind_shared(tag.ops,0);b2.bind_shared(tag.ops,0);aux::bandwidth_manager first(0),second(0);first.bind_shared_scope(global.ops);second.bind_shared_scope(tag.ops);auto x=std::make_shared<Socket>(),y=std::make_shared<Socket>();aux::bandwidth_channel* ac[]={&a1,&a2};aux::bandwidth_channel* bc[]={&b1,&b2};for(int n=0;n<100;++n){if(!first.queue_size())x->total+=first.request_bandwidth(x,1,1,ac,2);if(!second.queue_size())y->total+=second.request_bandwidth(y,1,1,bc,2);scope.clock.now+=100000000;first.update_quotas(lt::milliseconds(100));second.update_quotas(lt::milliseconds(100));}require(x->total+y->total==std::min(limits[0],limits[1])*10,"global/tag composed budget duplicated or stalled");require(x->total&&y->total,"global/tag combination starved owner");first.close();second.close();}}
void localConstraint(){Scope scope;Budget common(scope,1,10,0);aux::bandwidth_channel a,b,local;a.bind_shared(common.ops,0);b.bind_shared(common.ops,0);local.throttle(1);aux::bandwidth_manager first(0),second(0);first.bind_shared_scope(common.ops);second.bind_shared_scope(common.ops);auto x=std::make_shared<Socket>(),y=std::make_shared<Socket>();aux::bandwidth_channel* ac[]={&a,&local};aux::bandwidth_channel* bc[]={&b};for(int n=0;n<100;++n){if(!first.queue_size())x->total+=first.request_bandwidth(x,1,1,ac,2);if(!second.queue_size())y->total+=second.request_bandwidth(y,1,1,bc,1);scope.clock.now+=100000000;first.update_quotas(lt::milliseconds(100));second.update_quotas(lt::milliseconds(100));}require(x->total==10&&y->total>0,"blocked local constraint held the shared turn");first.close();second.close();}
void removedDisabledMembership(){Scope scope;Budget disabled(scope,1,-1,0);aux::bandwidth_channel channel;channel.bind_shared(disabled.ops,0);aux::bandwidth_manager manager(0);manager.bind_shared_scope(disabled.ops);biglybtc_shared_quota_scope_close_v1(scope.value);auto peer=std::make_shared<Socket>();aux::bandwidth_channel* before[]={&channel};manager.request_bandwidth(peer,10,1,before,1);scope.clock.now=1000000000;manager.update_quotas(lt::milliseconds(1000));require(!peer->total,"closed-scope baseline");manager.refresh_peer_channels(peer.get(),nullptr,0);manager.update_quotas(lt::milliseconds(0));require(peer->total==10&&!manager.queue_size(),"removed closed tag retained old queued constraint");manager.close();}
void refreshedPartialRefund(){Scope scope;Budget tagged(scope,1,10,0),global(scope,99,10,0);aux::bandwidth_channel tag,all;tag.bind_shared(tagged.ops,0);all.bind_shared(global.ops,0);aux::bandwidth_manager manager(0);manager.bind_shared_scope(tagged.ops);auto peer=std::make_shared<Socket>();aux::bandwidth_channel* before[]={&tag,&all};manager.request_bandwidth(peer,1000,1,before,2);scope.clock.now=1000000000;manager.update_quotas(lt::milliseconds(1000));require(!peer->total,"pending partial should not be delivered");aux::bandwidth_channel* after[]={&all};manager.refresh_peer_channels(peer.get(),after,1);require(tagged.ops.available(tagged.ops.budget,0)==10,"removed tag lost reserved quota");require(global.ops.available(global.ops.budget,0)==10,"unchanged global lost reserved quota");peer->disconnecting=true;manager.update_quotas(lt::milliseconds(0));require(global.ops.available(global.ops.budget,0)==10,"refresh/disconnect duplicated quota return");manager.close();}
void closeReturnsUndeliveredCredit(){Scope scope;Budget budget(scope,1,10,0);aux::bandwidth_channel a,b;a.bind_shared(budget.ops,0);b.bind_shared(budget.ops,0);aux::bandwidth_manager first(0),second(0);first.bind_shared_scope(budget.ops);second.bind_shared_scope(budget.ops);auto x=std::make_shared<Socket>(),y=std::make_shared<Socket>();aux::bandwidth_channel* ac[]={&a};aux::bandwidth_channel* bc[]={&b};first.request_bandwidth(x,1000,1,ac,1);scope.clock.now=1000000000;first.update_quotas(lt::milliseconds(1000));first.close();require(!x->total&&budget.ops.available(budget.ops.budget,0)==10,"closing manager delivered or stranded undelivered shared credit");y->total+=second.request_bandwidth(y,10,1,bc,1);second.update_quotas(lt::milliseconds(0));require(y->total==10,"remaining manager could not reuse closed owner's credit");second.close();}
void passiveOverhead(){Scope scope;Budget b(scope,1,10,0);aux::bandwidth_channel channel;require(channel.bind_shared(b.ops,0),"passive bind");channel.use_quota(0);channel.use_quota(7);scope.clock.now=1000000000;require(b.ops.epoch(b.ops.budget)&&channel.quota_left()==3,"passive IP overhead must charge debt without poisoning scope");}
void foreign(){Scope a,b;Budget x(a,1,10,0),y(b,1,10,0);aux::bandwidth_manager manager(0);require(manager.bind_shared_scope(x.ops),"first scope");require(!manager.bind_shared_scope(y.ops),"foreign scope accepted");auto bad=x.ops;bad.size--;aux::bandwidth_channel c;require(!c.bind_shared(bad,0),"malformed callbacks accepted");require(!c.bind_shared(x.ops,2),"bad direction accepted");manager.close();}
void smallReadsWithPendingOwner(){Scope scope;Budget budget(scope,1,16,0);aux::bandwidth_channel a,b;a.bind_shared(budget.ops,0);b.bind_shared(budget.ops,0);aux::bandwidth_manager first(0),second(0);first.bind_shared_scope(budget.ops);second.bind_shared_scope(budget.ops);auto bulk=std::make_shared<Socket>(),header=std::make_shared<Socket>();aux::bandwidth_channel* ac[]={&a};aux::bandwidth_channel* bc[]={&b};require(first.request_bandwidth(bulk,1000,1,ac,1)==0,"pending bulk owner");scope.clock.now=3000000000;const int immediate=second.request_bandwidth(header,1,1,bc,1);require(immediate==1,"one-byte protocol read paid a whole SDK tick despite shared one-second slack");require(budget.ops.available(budget.ops.budget,0)==47,"small fast request duplicated common credit");first.close();second.close();}
void closedScopeDropsInternalCredit(){Scope scope;Budget budget(scope,1,10,0);aux::bandwidth_channel channel;channel.bind_shared(budget.ops,0);aux::bandwidth_manager manager(0);manager.bind_shared_scope(budget.ops);auto peer=std::make_shared<Socket>();aux::bandwidth_channel* channels[]={&channel};require(manager.request_bandwidth(peer,1000,1,channels,1)==0,"partial credit queue");scope.clock.now=1000000000;manager.update_quotas(lt::milliseconds(1000));require(!peer->total&&manager.queued_bytes()==990,"credit must still be internal");biglybtc_shared_quota_scope_close_v1(scope.value);for(int n=0;n<30;++n){scope.clock.now+=500000000;manager.update_quotas(lt::milliseconds(500));}require(!peer->total&&manager.queued_bytes()==1000,"closed scope leaked internal credit after old request TTL");manager.close();}
void disabledRetainsProtocol(){Scope scope;Budget budget(scope,1,-1,0);aux::bandwidth_channel channel;channel.bind_shared(budget.ops,0);aux::bandwidth_manager manager(0);manager.bind_shared_scope(budget.ops);auto protocol=std::make_shared<Socket>();aux::bandwidth_channel* channels[]={&channel};require(manager.request_bandwidth(protocol,128,1,channels,1)==128,"disabled payload flag blocked protocol quota");require(budget.ops.limit(budget.ops.budget,0)==-1,"disabled payload metadata lost");manager.close();}
int main(){try{localFraction();twoManagers();refundAndClosure();passiveOverhead();intersectingBudgets();globalComposition();localConstraint();removedDisabledMembership();refreshedPartialRefund();closeReturnsUndeliveredCredit();foreign();smallReadsWithPendingOwner();closedScopeDropsInternalCredit();disabledRetainsProtocol();std::cout<<"PASS_SHARED_QUOTA_MANAGERS "<<checks<<" assertions;actual bandwidth limit/manager/queue TUs;no session/transport claim\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
